import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_as_not_converted():
    events = [{"converted": flag} for flag in (True, None, False, None)]
    assert conversion_rate(events) == 0.25
    assert conversion_rate([{"converted": None}]) == 0.0


def test_conversion_rate_empty():
    assert conversion_rate([]) == 0.0
    assert isinstance(conversion_rate([]), float)


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "small": [{"converted": True}],
        "large": [{"converted": flag} for flag in (False, None, False)],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_conversion_rate_without_sessions(groups):
    assert pooled_conversion_rate(groups) == 0.0
    assert isinstance(pooled_conversion_rate(groups), float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 3, 0)],
)
def test_conversions_in_window(counts, days, expected):
    assert conversions_in_window(counts, days) == expected


def test_parse_session_log_flags_and_field_whitespace():
    assert parse_session_log([" a , 1 , 1 \n", "b, -2, 0", " c , 3 , \t"]) == [
        session("a", 1, True), session("b", -2, False), session("c", 3, None)
    ]


def test_parse_session_log_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "# comment", " \t# another,comment", "a,1,1", "", "b#id,2,0"]
    assert parse_session_log(iter(lines)) == [session("a", 1, True), session("b#id", 2, False)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_session_log(["", " # comment", "a,1,1", " \t", bad_line])


def test_dedupe_sessions_keeps_last_duplicate_id_then_sorts():
    events = [
        session("a", 10, True), session("b", 2, True),
        session("c", 1, False), session("a", 2, None),
        session("b", 2, False),
    ]
    assert dedupe_sessions(events) == [events[2], events[3], events[4]]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_fills_range_and_ignores_outside():
    events = [
        session("before", 0, True), session("a", 1, True),
        session("b", 1, True), session("c", 2, False),
        session("d", 2, None), session("e", 3, True),
        session("after", 5, True),
    ]
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 1, 0]
    assert daily_conversion_counts(events, 1, 1) == [2]
    assert daily_conversion_counts(events, 4, 1) == []
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]


def test_campaign_summary_uses_calendar_days_pooled_rate_and_nonempty_groups():
    groups = {
        "small": [session("a", 1, True)],
        "large": [session("b", 3, False), session("c", 5, None)],
        "empty": [],
    }
    assert campaign_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 5)["recent"] == 1
    assert campaign_summary(groups, 20)["recent"] == 1
    assert campaign_summary(groups, 0)["recent"] == 0


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_without_sessions(groups):
    assert campaign_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"converted": True}],
        "empty": [],
        "low": [{"converted": None}],
        "a": [{"converted": True}],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "low"]
    assert top_converting_groups(groups, 0) == []
    assert top_converting_groups({"empty": []}, 1) == []
    assert top_converting_groups({}, 1) == []


def test_conversion_rate_by_group_sorts_keys_and_marks_empty_groups():
    groups = {"z": [], "b": [{"converted": False}], "a": [{"converted": True}, {"converted": None}]}
    result = conversion_rate_by_group(groups)
    assert result == {"a": 0.5, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 0, 3, 4, 5], 3),
     ([1, -1, 2], 1), ([1, 2, 3, 0, 1], 3)],
)
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected

